  const string Anchor="11111111-1111-4111-8111-111111111111",Campaign="22222222-1111-4111-8111-111111111111",Area="0123456789abcdef0123456789abcdef",OtherArea="fedcba9876543210fedcba9876543210";
  static int Main()
  {
   var t=new TestRunner();
   t.Run("six-pair native request has one exact cold load and no save/reservation authority",()=>{
    var f=SixPair();Valid(f.Request);var a=f.Scope();
    TestRunner.True(f.Request.SelectedChunk7Scenario=="chunk7-two-pair-exploration"&&f.Request.OwnedPairs.PairIds.Length==12&&a.MatchesOwnedPairsPlan(true,true),"Six-pair request lost exact source or all twelve roles.");
    TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Six-pair sole native load refused.");
    TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Six-pair second native load admitted.");
    TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Load,f.Root)!=null,"Six-pair read-only scope gained a write.");
    TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Six-pair refused write spent authority.");TestRunner.Equal(0,a.OwnedPairsReservationCount,"Six-pair scope reserved an output.");
   });
   foreach(var mutation in new[]{"producer-as-qualifier","source-artifact","source-archive","eleven","thirteen","duplicate","role","write","second-load","checkpoint","progression","name","length","ticks"})t.Run("six-pair exact native request refuses "+mutation,()=>{
    var f=SixPair();var s=f.Request.OwnedPairs;
    switch(mutation){
     case "producer-as-qualifier":s.SourceRunId="20261022-c7b-world184-b184s1-sixthhorse-manual";break;
     case "source-artifact":s.SourceArtifactSha256=new string('f',64);break;case "source-archive":s.SourceArchiveSha256=new string('f',64);break;
     case "eleven":s.PartyIds=s.PartyIds.Take(11).ToArray();break;case "thirteen":s.PartyIds=s.PartyIds.Concat(new[]{Guid.NewGuid().ToString("D")}).ToArray();break;
     case "duplicate":s.PartyIds[11]=s.PartyIds[0];break;case "role":s.RiderBId=s.RiderAId;break;
     case "write":s.ExpectedNativeWriteCount=1;break;case "second-load":s.ExpectedNativeLoadCount=2;break;
     case "checkpoint":f.Request.PersistenceCase="multi-exploration-manual";break;
     case "progression":s.XpAssistance=new Chunk7OwnerSeedXpAssistance{UnitId=s.RiderBId,TargetCharacterLevel=8};break;
     case "name":f.Request.PersistenceLoad.FileName="Manual_308_KMC_C7_WORLD.zks";break;
     case "length":f.Request.PersistenceLoad.Length++;break;case "ticks":f.Request.PersistenceLoad.LastWriteTimeUtcTicks++;break;
